insert into public.fact_supply (indicator_code, indicator_label, reference_year, source_id, universe, geo_level, geo_code, estimate, unit, precision_flag, observed_or_modeled, method_id, version) select t.indicator_code, t.indicator_label, 2026, s.id, 'Puntos de acceso del sistema financiero', t.geo_level, t.geo_code, t.estimate, 'puntos', 'high', 'observed', m.id, '2026-10-17' from _cnbv t join public.source_document s on s.source_code = 'cnbv_inclusion_databases' join public.dim_method m on m.method_code = 'official_published_aggregate' where not exists (select 1 from public.fact_supply f where f.indicator_code = t.indicator_code and f.reference_year = 2026 and f.geo_level = t.geo_level and f.geo_code = t.geo_code and f.version = '2026-10-17');
insert into public.dim_segment(segment_code, dimension, value, label) select distinct lower(regexp_replace(k||'_'||left(v, 80),'[^a-zA-Z0-9]+','_','g')), k, v, left(v, 180) from public.fact_estimate, jsonb_each_text(segment_json) e(k,v) on conflict (segment_code) do nothing;
